/* Latte Dark v1.0.0 - SHIKI KUJO OFFICIAL STORE */
:root {
  --latte-bg:      #2b211b;
  --latte-bg-2:    #231a15;
  --latte-bg-3:    #1b1310;
  --latte-text:    #f1e4d3;
  --latte-accent:  #d8955f;
}
.theme-dark, .theme-darker, .theme-light {
  --background-primary:            var(--latte-bg);
  --background-secondary:          var(--latte-bg-2);
  --background-secondary-alt:      var(--latte-bg-3);
  --background-tertiary:           var(--latte-bg-3);
  --channeltextarea-background:    var(--latte-bg-3);
  --text-normal:                   var(--latte-text);
  --brand-experiment:              var(--latte-accent);
  --interactive-active:            var(--latte-accent);
}
